def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive = []
    prev_bids = []
    prev_named = {}
    for agent_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append((agent_id, opp))
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(bid)
                prev_named[agent_id] = bid

    if not alive:
        base = DAILY_SALARY * 0.18
        if hp <= 2 or no_water_days >= 2:
            base = DAILY_SALARY * 0.75
        return max(0.0, min(budget, base))

    alive_count = len(alive)
    severe_need = hp <= 2 or no_water_days >= 2
    urgent_need = hp <= 4 or no_water_days >= 1
    scarce = supply <= 16
    tight = supply <= 19

    highest_prev = max(prev_bids) if prev_bids else 0.0
    bob_prev = prev_named.get('Bob', 0.0)
    cindy_prev = prev_named.get('Cindy', 0.0)

    base = DAILY_SALARY * 0.38

    if alive_count <= 1:
        base = DAILY_SALARY * 0.22
    elif alive_count == 2:
        base = DAILY_SALARY * 0.32

    if tight:
        base += 6.0
    if scarce:
        base += 8.0

    if highest_prev >= 110:
        if severe_need:
            base = max(base, min(DAILY_SALARY * 0.92, highest_prev * 0.78))
        elif urgent_need:
            base = max(base, DAILY_SALARY * 0.62)
        else:
            base = min(base, DAILY_SALARY * 0.42)
    elif highest_prev >= 70:
        if urgent_need:
            base = max(base, min(DAILY_SALARY * 0.88, bob_prev + 4.0 if bob_prev > 0 else highest_prev + 2.0))
        else:
            base = max(base, DAILY_SALARY * 0.48)
    elif highest_prev > 0:
        base = max(base, highest_prev + 2.0)

    if cindy_prev >= 120 and not urgent_need:
        base = min(base, DAILY_SALARY * 0.4)

    if severe_need:
        base = max(base, DAILY_SALARY * 0.9)
        if scarce:
            base = max(base, DAILY_SALARY * 0.96)
    elif urgent_need:
        base = max(base, DAILY_SALARY * 0.68)
        if scarce:
            base = max(base, DAILY_SALARY * 0.78)

    if budget < DAILY_SALARY * 1.2:
        base = min(base, budget)
    elif budget > DAILY_SALARY * 8 and severe_need:
        base = max(base, DAILY_SALARY * 0.98)

    if day >= 8 and hp > 5 and not urgent_need:
        base = min(base, DAILY_SALARY * 0.36)

    bid = max(0.0, min(budget, base))
    return bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.1)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    my_bid = DAILY_SALARY * 0.55 # Default moderate bid

    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

        high_competition_threshold = DAILY_SALARY * 0.85

        if highest_prev_bid >= high_competition_threshold:
            if my_status['hp'] > 4:
                my_bid = DAILY_SALARY * 0.7
            else:
                my_bid = DAILY_SALARY * 0.95
        else:
            my_bid = max(DAILY_SALARY * 0.5, highest_prev_bid + 2.5)

            if my_status['hp'] <= 4:
                my_bid = max(my_bid, DAILY_SALARY * 0.8)

    else:
        if my_status['hp'] <= 2:
            my_bid = DAILY_SALARY * 0.9
        elif my_status['hp'] <= 4:
            my_bid = DAILY_SALARY * 0.7
        else:
            my_bid = DAILY_SALARY * 0.55

    current_day = day_context['day']
    if current_day > EPISODE_DAYS * 0.7:
        my_bid *= 1.1

    final_bid = min(my_status['budget'], my_bid)
    final_bid = max(final_bid, 1.0)

    if my_status['hp'] > 2:
        final_bid = min(final_bid, DAILY_SALARY * 1.2)
    else:
        final_bid = min(final_bid, my_status['budget'])

    return final_bid

