            yesterday_bids.append(prev['bid'])

    avg_prev = sum(yesterday_bids) / len(yesterday_bids) if yesterday_bids else 75

    if my_status['hp'] <= 4:
        return min(my_status['budget'], DAILY_SALARY * 1.2)

